require "cucumber/rails"
require "capybara/minitest"

ActionController::Base.allow_rescue = false

# Cucumber::Rails::Database wraps every scenario: non-javascript scenarios run
# inside a transaction that rolls back, while @javascript scenarios run against
# the real database because the browser cannot share the test's connection —
# those truncate before the scenario and clean up after.
Cucumber::Rails::Database.javascript_strategy = :truncation

Capybara.default_max_wait_time = 5

# Mirror application_system_test_case.rb so cucumber drives the app the same
# way system tests do.
Capybara.register_driver :headless_chrome do |app|
  options = Selenium::WebDriver::Chrome::Options.new
  options.add_argument("--headless")
  options.add_argument("--window-size=1400,800")
  options.add_argument("--disable-gpu")
  options.add_argument("--disable-dev-shm-usage")
  options.add_argument("--no-sandbox")
  options.add_argument("--disable-search-engine-choice-screen")
  Capybara::Selenium::Driver.new(app, browser: :chrome, options: options)
end
Capybara.javascript_driver = :headless_chrome

World(Minitest::Assertions, Capybara::Minitest::Assertions)
